-- =====================================================================
-- GENERATED from the code's function declarations and BusinessTaxonomy; do not edit.
-- Regenerate with: INSYS_UPDATE_SNAPSHOTS=1 dotnet test --filter-class "*FunctionCatalogueTests"
-- Repeatable script: the migration runner re-runs it when its content changes.
-- New codes are added as version 1 from 1 October 2026, global and ACTIVE. A row that changed gets a new
-- version from today and the old one is closed; a code no longer declared is closed (SDM-002).
-- Then iam.adopt_function_catalogue() converts what still holds permissions (ADR-026 §7).
-- =====================================================================
-- iam.ref_business_domains
DROP TABLE IF EXISTS pg_temp.release_ref_business_domains;
CREATE TEMP TABLE release_ref_business_domains AS SELECT code, labels, sort_order, domain_code, icon FROM iam.ref_business_domains WITH NO DATA;
UPDATE iam.ref_business_domains c
   SET effective_to = CASE WHEN c.effective_from < current_date THEN current_date END,
       record_status = CASE WHEN c.effective_from < current_date THEN c.record_status ELSE 'RETIRED' END
 WHERE c.tenant_id IS NULL AND c.record_status = 'ACTIVE' AND c.effective_to IS NULL
   AND NOT EXISTS (SELECT 1 FROM release_ref_business_domains r WHERE r.code = c.code
                   AND ROW(r.labels, r.sort_order, r.domain_code, r.icon) IS NOT DISTINCT FROM ROW(c.labels, c.sort_order, c.domain_code, c.icon));
                     approved_by, change_reason, labels, sort_order, domain_code, icon)
SELECT NULL, r.code, COALESCE(v.latest, 0) + 1, CASE WHEN v.latest IS NULL THEN DATE '2026-10-01' ELSE current_date END, 'ACTIVE', 'insys-core',
       'PUBLIC', 'migration', now(), 'migration', 'Generated from the code''s declarations (ADR-026)', r.labels, r.sort_order, r.domain_code, r.icon
  FROM release_ref_business_domains r LEFT JOIN (SELECT code, max(version) AS latest FROM iam.ref_business_domains WHERE tenant_id IS NULL GROUP BY code) v ON v.code = r.code
 WHERE NOT EXISTS (SELECT 1 FROM iam.ref_business_domains c WHERE c.tenant_id IS NULL AND c.code = r.code AND c.record_status = 'ACTIVE' AND c.effective_to IS NULL);
DROP TABLE pg_temp.release_ref_business_domains;

