                     approved_by, change_reason, labels, sort_order, sub_domain_code, domain_code, icon)
SELECT NULL, r.code, COALESCE(v.latest, 0) + 1, CASE WHEN v.latest IS NULL THEN DATE '2026-10-01' ELSE current_date END, 'ACTIVE', 'insys-core',
       'PUBLIC', 'migration', now(), 'migration', 'Generated from the code''s declarations (ADR-026)', r.labels, r.sort_order, r.sub_domain_code, r.domain_code, r.icon
  FROM release_ref_business_sub_domains r LEFT JOIN (SELECT code, max(version) AS latest FROM iam.ref_business_sub_domains WHERE tenant_id IS NULL GROUP BY code) v ON v.code = r.code
 WHERE NOT EXISTS (SELECT 1 FROM iam.ref_business_sub_domains c WHERE c.tenant_id IS NULL AND c.code = r.code AND c.record_status = 'ACTIVE' AND c.effective_to IS NULL);
