-- iam.ref_function_catalogue
DROP TABLE IF EXISTS pg_temp.release_ref_function_catalogue;
CREATE TEMP TABLE release_ref_function_catalogue AS SELECT code, labels, sort_order, function_code, sub_domain_code, process_area, interaction_type, function_kind, parent_function_code, audiences, route_key, required_permissions, required_feature, privileged, allowed_while_onboarding FROM iam.ref_function_catalogue WITH NO DATA;
UPDATE iam.ref_function_catalogue c
   SET effective_to = CASE WHEN c.effective_from < current_date THEN current_date END,
       record_status = CASE WHEN c.effective_from < current_date THEN c.record_status ELSE 'RETIRED' END
 WHERE c.tenant_id IS NULL AND c.record_status = 'ACTIVE' AND c.effective_to IS NULL
   AND NOT EXISTS (SELECT 1 FROM release_ref_function_catalogue r WHERE r.code = c.code
                   AND ROW(r.labels, r.sort_order, r.function_code, r.sub_domain_code, r.process_area, r.interaction_type, r.function_kind, r.parent_function_code, r.audiences, r.route_key, r.required_permissions, r.required_feature, r.privileged, r.allowed_while_onboarding) IS NOT DISTINCT FROM ROW(c.labels, c.sort_order, c.function_code, c.sub_domain_code, c.process_area, c.interaction_type, c.function_kind, c.parent_function_code, c.audiences, c.route_key, c.required_permissions, c.required_feature, c.privileged, c.allowed_while_onboarding));
                     approved_by, change_reason, labels, sort_order, function_code, sub_domain_code, process_area, interaction_type, function_kind, parent_function_code, audiences, route_key, required_permissions, required_feature, privileged, allowed_while_onboarding)
SELECT NULL, r.code, COALESCE(v.latest, 0) + 1, CASE WHEN v.latest IS NULL THEN DATE '2026-10-01' ELSE current_date END, 'ACTIVE', 'insys-core',
       'PUBLIC', 'migration', now(), 'migration', 'Generated from the code''s declarations (ADR-026)', r.labels, r.sort_order, r.function_code, r.sub_domain_code, r.process_area, r.interaction_type, r.function_kind, r.parent_function_code, r.audiences, r.route_key, r.required_permissions, r.required_feature, r.privileged, r.allowed_while_onboarding
  FROM release_ref_function_catalogue r LEFT JOIN (SELECT code, max(version) AS latest FROM iam.ref_function_catalogue WHERE tenant_id IS NULL GROUP BY code) v ON v.code = r.code
 WHERE NOT EXISTS (SELECT 1 FROM iam.ref_function_catalogue c WHERE c.tenant_id IS NULL AND c.code = r.code AND c.record_status = 'ACTIVE' AND c.effective_to IS NULL);
DROP TABLE pg_temp.release_ref_function_catalogue;

SELECT iam.adopt_function_catalogue();
